    "explanation": "Doğru cevap A’dır. C. Difficile’nin temel patojenik ürünleri toksin A ve toksin B’dir; bu toksinler Rho, rac ve cdc42 gibi küçük GTPazları glukozile ederek aktin polimerizasyonunu ve hücre iskeleti düzenini bozar. Sonuçta epitel hücrelerinde yuvarlaklaşma, bariyer kaybı, inflamasyon ve psödomembran oluşumu gelişir. “Toksin A, adenilat siklaz aktivasyonu ile sulu ishale yol açan ısıya duyarlı enterotoksindir” seçeneği kolera ve enterotoksijenik E. Coli gibi adenilat siklaz/cAMP ilişkili patogenezleri çağrıştırır; “Toksinler yalnızca sinir-kas kavşağında asetilkolin salınımını engelleyerek etki gösterir” seçeneği botulinum/tetanoz nörotoksinleriyle, “Ana virülans faktörü, eritrosit membranında por oluşturan alfa toksindir” seçeneği ise Clostridium perfringens alfa toksiniyle daha uyumludur. Difficile toksin A ve toksin B, rho ailesi küçük GTPazlarını inaktive ederek enterositlerde sitoskeletal bütünlüğü bozar, epitel bariyer hasarı ve psödomembranöz kolit gelişimine neden olur. TUS açısından ayırıcı nokta: C. Difficile sorularında “antibiyotik sonrası kolit” kadar önemli ayırıcı bilgi toksin A/B’nin Rho GTPazları glukozile ederek aktin iskeletini bozmasıdır.",
