      "Hücre membran bütünlüğü genellikle geç döneme kadar korunur": "Doğrudur. Apoptozda membran bütünlüğü büyük ölçüde korunur ve hücresel içerik çevre dokuya kontrolsüz biçimde yayılmaz. Bu nedenle inflamasyon nekroza göre daha azdır.",
      "Fosfatidilserinin dış membran yaprağına taşınması fagositozu kolaylaştırır": "Doğrudur. Fosfatidilserinin dış yüzeye translokasyonu fagositler için “beni ye” sinyali oluşturur. Bu olay apoptotik hücrenin sessiz biçimde temizlenmesini sağlar.",
