    "explanation": "HBV serolojisinde pencere dönemi, yüzey antijeninin saptanamaz hâle geldiği ancak koruyucu anti-HBs antikorunun henüz ölçülebilir düzeye ulaşmadığı aralıktır. Bu aralıkta HBsAg negatif, anti-HBs negatif olabilir; bu nedenle bu iki belirtece bakmak tanıyı kaçırabilir. Anti-HBc IgM ise akut veya yakın dönem HBV enfeksiyonunu gösterir ve pencere döneminde tanısal olarak en değerlidir. HBeAg viral replikasyon ve bulaştırıcılık hakkında bilgi verir, pencere döneminin ana belirteci değildir. HBV pencere döneminde HBsAg kaybolmuş, anti-HBs henüz oluşmamıştır. Bu dönemde akut enfeksiyonu destekleyen en önemli serolojik belirteç anti-HBc IgM pozitifliğidir. TUS açısından ayırıcı nokta: HBV pencere dönemi denince HBsAg negatif, anti-HBs negatif, anti-HBc IgM pozitif mantığı akılda tutulmalıdır.",
    "answerAnalysisIntro": "Bu soru HBV belirteçlerini zaman ekseninde yorumlamayı ölçer. Pencere döneminin mantığı, yüzey antijeni ile yüzey antikoru arasındaki boşluğu yakalamaktır.",
