    "explanation": "Primer adrenal yetmezlikte sorun adrenal bezdedir; bu nedenle kortizol üretimi düşer ve hipofizden ACTH salınımı artar. ACTH artışı POMC türevleriyle ilişkili melanosit uyarıcı etki nedeniyle hiperpigmentasyona yol açabilir. Mineralokortikoid eksikliği nedeniyle sodyum kaybı, hipovolemi, hipotansiyon, hiperkalemi ve renin artışı beklenir. Sekonder adrenal yetmezlikte ise ACTH düşük veya uygunsuz normal olabilir; aldosteron sistemi genellikle daha korunmuştur. Primer adrenal yetmezlikte adrenal korteks hormon üretimi bozulur; kortizol ve aldosteron azalır. Negatif geri bildirim kaybı ACTH artışına, ACTH ile ilişkili POMC türevleri ise hiperpigmentasyona yol açabilir. TUS açısından ayırıcı nokta: Primer adrenal yetmezlik: düşük kortizol + yüksek ACTH + hiperpigmentasyon + hiperkalemi. Sekonderde ACTH düşük ve aldosteron çoğunlukla korunur.",
