    "explanation": "Doğru cevap A’dır. G6PD eksikliğinde pentoz fosfat yolundan yeterli NADPH üretilemez. NADPH, okside glutatyonun tekrar indirgenmiş glutatyona çevrilmesi için gereklidir; indirgenmiş glutatyon ise peroksitleri ve reaktif oksijen türlerini detoksifiye eder. Eritrositlerde mitokondri olmadığı için alternatif antioksidan kapasite sınırlıdır. Oksidatif ilaçlar, enfeksiyonlar veya bakla gibi tetikleyiciler hemoglobin denatürasyonuna, heinz cisimciklerine ve hemolize yol açabilir. Beta zincir sentez kusuru talasemilerle, pirüvat metabolizması ise farklı enerji bozukluklarıyla ilişkilidir. G6PD, pentoz fosfat yolunun NADPH üreten ana enzimlerinden biridir. Eritrositler mitokondri içermediği için oksidatif strese karşı özellikle NADPH–indirgenmiş glutatyon sistemine bağımlıdır. TUS açısından ayırıcı nokta: G6PD eksikliği sorularında tetikleyici oksidatif stres ise mekanizma NADPH ve indirgenmiş glutatyon yetersizliğidir; heinz cisimcikleri ve bite cell bulguları beklenebilir.",
    "answerAnalysisIntro": "Bu soru pentoz fosfat yolunu eritrosit fizyolojisiyle bağlar. Ana zincir: G6PD azalır → NADPH azalır → indirgenmiş glutatyon azalır → oksidatif hemoliz artar.",
