    "coreKnowledge": "Parathormon serum kalsiyumunu artırırken serum fosfatını düşürme eğilimindedir. Bunu böbrekte kalsiyum geri emilimini ve 1-alfa hidroksilaz aktivitesini artırarak, proksimal tübülde fosfat geri emilimini ise azaltarak yapar.",
    "explanation": "Doğru cevap D’dir. Parathormonun böbrekteki önemli etkilerinden biri proksimal tübülde fosfat geri emilimini azaltmasıdır; bu nedenle fosfatüri gelişir ve serum fosfatı düşme eğilimindedir. Buna karşılık distal tübülde kalsiyum geri emilimi artar, böbrekte 1-alfa hidroksilaz uyarılır ve aktif D vitamini sentezi artar. Kemikte ise PTH osteoblast üzerindeki RANKL ekspresyonunu artırarak osteoklast aktivasyonunu dolaylı biçimde güçlendirir. Bu nedenle fosfat geri emiliminin artması PTH etkisiyle uyumlu değildir. Parathormon serum kalsiyumunu artırırken serum fosfatını düşürme eğilimindedir. Bunu böbrekte kalsiyum geri emilimini ve 1-alfa hidroksilaz aktivitesini artırarak, proksimal tübülde fosfat geri emilimini ise azaltarak yapar. TUS açısından ayırıcı nokta: PTH: kalsiyumu artırır, fosfatı düşürür. Böbrekte kalsiyum geri emilimi artar; fosfat geri emilimi azalır.",
    "answerAnalysisIntro": "Bu soruda PTH’nin kalsiyumu artırırken fosfatı neden düşürdüğünü mekanizma düzeyinde ayırmak gerekir. Ana tuzak, kalsiyum ve fosfatın kemikten birlikte çıkmasına rağmen böbrekte fosfat kaybının artmasıdır.",
