      "HIV gp120, CD4 molekülüne bağlandıktan sonra CCR5 veya CXCR4 koreseptörlerinden yararlanabilir": "Doğrudur. HIV gp120 ile CD4’e bağlanır ve ardından CCR5 veya CXCR4 koreseptörlerini kullanır. Bu bağlanma dizisi viral girişin temel basamağıdır.",
      "CCR5 koreseptörü yalnızca B lenfositlerinde bulunur ve makrofaj tropizmiyle ilişkili değildir": "Yanlıştır. CCR5 özellikle makrofaj-tropik suşlar ve erken enfeksiyon açısından önemlidir. Yalnızca B lenfositleriyle sınırlı bir koreseptör olarak düşünülmez.",
