        "CCR5 koreseptörü yalnızca B lenfositlerinde bulunur ve makrofaj tropizmiyle ilişkili değildir": "Yanlıştır. CCR5 özellikle makrofaj-tropik suşlar ve erken enfeksiyon açısından önemlidir. Yalnızca B lenfositleriyle sınırlı bir koreseptör olarak düşünülmez.",
        "CXCR4 kullanımı virüsün eritrositlere doğrudan girişini sağlar": "Yanlıştır. CXCR4 kullanımı T hücre tropizmiyle ilişkilidir; eritrositler CD4 çekirdek reseptör sistemine sahip hedef hücreler değildir. HIV eritrositlere bu yolla doğrudan girmez.",
        "gp41, revers transkriptaz aktivitesini sağlayan nükleer enzimdir": "Yanlıştır. Gp41 membran füzyonunda görevli viral zarf proteinidir. Revers transkriptaz ise viral RNA’dan DNA sentezleyen enzimdir ve gp41 değildir."
