    "correctAnswer": "C",
    "correctOptionText": "Glutatyon depolarını yenileyerek NAPQI detoksifikasyonunu artırması",
    "coreKnowledge": "Parasetamol aşırı dozunda toksik metabolit NAPQI artar ve glutatyon depoları tükenirse hepatoselüler nekroz gelişir. N-asetilsistein sistein kaynağı sağlayarak glutatyon sentezini destekler ve NAPQI detoksifikasyonunu artırır.",
    "explanation": "Doğru cevap A’dır. Parasetamol normal dozlarda çoğunlukla glukuronidasyon ve sülfatlama ile metabolize edilir; küçük bir kısmı CYP aracılığıyla NAPQI’ye dönüşür. NAPQI normalde glutatyonla bağlanarak zararsız hâle getirilir. Aşırı dozda glutatyon depoları tükenir ve NAPQI hepatosit proteinlerine bağlanarak özellikle santral lobüler karaciğer hasarı oluşturur. N-asetilsistein glutatyon sentezi için sistein sağlar ve toksik metabolitin detoksifikasyonunu artırır. Diğer seçenekler aspirin, opioid, metanol/etilen glikol veya yanlış CYP mantığıyla ilgilidir. Parasetamol aşırı dozunda toksik metabolit NAPQI artar ve glutatyon depoları tükenirse hepatoselüler nekroz gelişir. N-asetilsistein sistein kaynağı sağlayarak glutatyon sentezini destekler ve NAPQI detoksifikasyonunu artırır. TUS açısından ayırıcı nokta: Parasetamol toksisitesi = NAPQI birikimi + glutatyon tükenmesi; antidot N-asetilsistein glutatyonu yeniler.",
    "answerAnalysisIntro": "Bu soru antidot bilgisini toksik metabolit üzerinden sorgular. Parasetamol toksisitesinde hedef molekül NAPQI, koruyucu sistem ise glutatyondur.",
    "optionFeedback": {
      "Siklooksijenaz-1’i irreversibl inhibe ederek prostaglandin sentezini durdurması": "Yanlıştır. COX-1’in irreversibl inhibisyonu aspirinle ilişkilidir. Parasetamol toksisitesinde hepatoproteksiyon COX inhibisyonuyla açıklanmaz.",
      "Opioid reseptör antagonizmasıyla solunum depresyonunu düzeltmesi": "Yanlıştır. Opioid reseptör antagonizması naloksonun mekanizmasıdır. Parasetamol zehirlenmesinde solunum depresyonu değil hepatotoksik metabolit birikimi temel problemdir.",
      "Glutatyon depolarını yenileyerek NAPQI detoksifikasyonunu artırması": "Doğrudur. N-asetilsistein glutatyon öncülü olarak çalışır ve NAPQI’nin glutatyonla konjugasyonunu artırır. Bu mekanizma hepatotoksisiteyi azaltır.",
      "Alkol dehidrogenazı inhibe ederek toksik metabolit oluşumunu engellemesi": "Yanlıştır. Alkol dehidrogenaz inhibisyonu fomepizol/etanol ile metanol ve etilen glikol zehirlenmelerinde kullanılır. Parasetamol toksisitesinin antidotu bu mekanizma üzerinden etki etmez.",
      "Sitokrom P450 enzimlerini kalıcı olarak aktive ederek parasetamol atılımını hızlandırması": "Yanlıştır. CYP aktivasyonunun artması NAPQI oluşumunu artırarak toksisiteyi kötüleştirebilir. N-asetilsistein CYP’yi kalıcı aktive ederek değil glutatyonu yenileyerek korur."
    },
