      "RhD-negatif, duyarlanmamış gebede RhD-pozitif bebek doğumu sonrası profilaksi": "Uygun endikasyondur. RhD-negatif duyarlanmamış anne RhD-pozitif bebek doğurduysa postpartum anti-D profilaksisi alloimmünizasyonu önlemek için verilir.",
      "RhD-negatif, duyarlanmamış gebede invaziv prenatal işlem sonrası profilaksi": "Uygun endikasyondur. Amniyosentez veya koryon villus örneklemesi gibi invaziv prenatal işlemler fetomaternal kanama riski taşır.",
      "RhD-negatif, duyarlanmamış gebede ikinci trimester kanaması sonrası profilaksi": "Uygun endikasyondur. Gebelikte kanama fetomaternal eritrosit geçişine yol açabilir; rhD-negatif duyarlanmamış gebede profilaksi düşünülür.",
      "RhD-negatif, duyarlanmamış gebede abdominal travma sonrası profilaksi": "Uygun endikasyondur. Abdominal travma fetomaternal kanama riski oluşturabilir ve RhD-negatif duyarlanmamış gebede anti-D profilaksisi gerektirebilir."
