    "coreKnowledge": "Nervus pudendus S2-S4 ventral dallarından köken alan somatik bir sinirdir. Perine duyusu, eksternal anal sfinkter ve eksternal üretral sfinkter gibi istemli kasların innervasyonunda önemlidir.",
    "explanation": "Doğru cevap A’dır. Nervus pudendus sakral pleksustan, özellikle S2-S4 köklerinden kaynaklanır. Pelvisten foramen ischiadicum majus yoluyla çıkar, spina ischiadica/sakrospinal ligament çevresinden dolanır ve foramen ischiadicum minus ile perineye girerek pudendal kanalda seyreder. Perinenin önemli somatik duyusunu ve eksternal anal/üretral sfinkter gibi çizgili kasların motor innervasyonunu sağlar. Obturator sinir adduktor kompartmanla, femoral sinir kuadrisepsle, otonomik lifler ise düz kas ve viseral fonksiyonlarla daha ilişkilidir. Nervus pudendus S2-S4 ventral dallarından köken alan somatik bir sinirdir. Perine duyusu, eksternal anal sfinkter ve eksternal üretral sfinkter gibi istemli kasların innervasyonunda önemlidir. TUS açısından ayırıcı nokta: Pudendal sinir = S2-S4 + perinenin somatik siniri + eksternal anal/üretral sfinkter kontrolü. Obturator sinir adduktorları innerve eder.",
    "answerAnalysisIntro": "Bu soru pudendal siniri yalnız kökleriyle değil, somatik fonksiyonu ve sfinkter kontrolüyle birlikte sorgular. S2-S4 bilgisi parasempatik liflerle karıştırılmamalıdır.",
