        "keyClues": [
          "SIADH’de ADH fazlalığı su tutulmasına, dilüsyonel hiponatremiye ve düşük serum osmolalitesine yol açar. Ancak natriürez ve su dengesi nedeniyle klinik tablo genellikle övolemiktir; belirgin ödem beklenmez.",
          "SIADH = övolemik hiponatremi + düşük serum osm + uygunsuz yüksek idrar osm + genellikle yüksek idrar Na; belirgin ödem beklenmez."
        ],
