      "IgE aracılı mast hücre degranülasyonu ile dakikalar içinde gelişir": "Yanlıştır. IgE aracılı mast hücre degranülasyonu Tip I aşırı duyarlılık mekanizmasıdır. Anafilaksi, alerjik rinit ve ürtiker bu gruba örnek verilebilir.",
      "Antijen-antikor komplekslerinin damar duvarına çökmesiyle kompleman aktivasyonu oluşturur": "Yanlıştır. Antijen-antikor komplekslerinin çökmesi ve kompleman aktivasyonu Tip III aşırı duyarlılıktır. Serum hastalığı, bazı vaskülitler ve poststreptokokal glomerülonefrit bu mantıkla düşünülür.",
