    "coreKnowledge": "Nervus laryngeus recurrens, vagus sinirinin dalıdır ve cricothyroideus dışındaki intrinsik larenks kaslarını innerve eder. Hasarında ses kısıklığı, vokal kord hareket bozukluğu ve bilateral hasarda hava yolu problemi gelişebilir.",
    "explanation": "Doğru cevap A’dır. Recurrent laryngeal sinir tiroid cerrahisi ve boyun cerrahisi açısından kritik anatomik yapıdır. Bu sinir larenksin intrinsik kaslarının çoğunu innerve eder; istisna m. Cricothyroideus olup external laryngeal sinir tarafından innerve edilir. Recurrent laryngeal sinir hasarında vokal kord abdüksiyon/adduksiyon fonksiyonları etkilenir ve ses kısıklığı ortaya çıkabilir. Dil duyusu trigeminal/fasiyal/glossofaringeal sinirlerle, çiğneme kasları mandibular sinirle, parotis parasempatik innervasyonu ise glossofaringeal sinir yoluyla ilişkilidir. Nervus laryngeus recurrens, vagus sinirinin dalıdır ve cricothyroideus dışındaki intrinsik larenks kaslarını innerve eder. Hasarında ses kısıklığı, vokal kord hareket bozukluğu ve bilateral hasarda hava yolu problemi gelişebilir. TUS açısından ayırıcı nokta: Larenks kaslarında istisna: cricothyroid kas external laryngeal sinir; diğer intrinsik kasların çoğu recurrent laryngeal sinir.",
    "answerAnalysisIntro": "Bu soru larenks innervasyonunda ana istisnayı sorgular. Recurrent laryngeal sinir çoğu intrinsik kası innerve eder; cricothyroid kas istisnadır.",
