      "Dilin ön üçte ikisinde genel duyu kaybı": "Yanlıştır. Dilin ön üçte ikisinde genel duyu n. Lingualis ile taşınır. Recurrent laryngeal sinir dil duyusunun ana siniri değildir.",
      "Parotis bezinde parasempatik sekresyonun tamamen durması": "Yanlıştır. Parotis bezinin parasempatik innervasyonu n. Glossopharyngeus, n. Tympanicus, n. Petrosus minor ve otik ganglion üzerinden sağlanır. Recurrent laryngeal hasar parotis sekresyonunu temel olarak durdurmaz.",
      "M. masseter ve temporal kas motor innervasyonunun kaybı": "Yanlıştır. Masseter ve temporal kaslar n. Trigeminus mandibular dalı tarafından innerve edilir. Recurrent laryngeal sinir çiğneme kaslarını innerve etmez.",
      "Yumuşak damakta yalnızca tat duyusunun kaybı": "Yanlıştır. Yumuşak damak ve tat duyusu farklı kraniyal sinir dallarıyla ilişkilidir. Recurrent laryngeal sinirin temel klinik etkisi larenks kasları ve ses fonksiyonudur.",
